-- Epi-Card QL Conjugate System v1.0.0
-- Portable/offline schema for SQLite 3.45+
-- IDs are UUIDv7 strings generated by the runtime before INSERT.
-- Timestamps are RFC 3339 UTC strings unless a local civil time is explicitly named.
-- JSON columns are TEXT checked with json_valid().

PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
PRAGMA synchronous = NORMAL;

BEGIN;

CREATE TABLE schema_revision (
  version TEXT PRIMARY KEY,
  applied_at TEXT NOT NULL,
  specification_hash TEXT NOT NULL CHECK(length(specification_hash)=64),
  notes TEXT
);

CREATE TABLE actor (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL CHECK(kind IN ('human','agent','service','provider')),
  display_name TEXT,
  external_ref TEXT,
  disclosure TEXT NOT NULL DEFAULT 'private' CHECK(disclosure IN ('secret','private','shared','public')),
  metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata)),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(kind, external_ref)
);

CREATE TABLE pasu (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL CHECK(kind IN ('human','collective','anonymous','other')),
  public_handle TEXT,
  private_profile_ref TEXT,
  locale TEXT,
  timezone_default TEXT,
  consent_profile TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(consent_profile)),
  created_by TEXT REFERENCES actor(id),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE pasu_attribute (
  id TEXT PRIMARY KEY,
  pasu_id TEXT NOT NULL REFERENCES pasu(id) ON DELETE CASCADE,
  attribute_type TEXT NOT NULL,
  value TEXT NOT NULL CHECK(json_valid(value)),
  source_ref TEXT,
  valid_from TEXT,
  valid_to TEXT,
  disclosure TEXT NOT NULL DEFAULT 'private' CHECK(disclosure IN ('secret','private','shared','public')),
  external_provider_ok INTEGER NOT NULL DEFAULT 0 CHECK(external_provider_ok IN (0,1)),
  created_by TEXT REFERENCES actor(id),
  created_at TEXT NOT NULL,
  CHECK(valid_to IS NULL OR valid_from IS NULL OR valid_to > valid_from)
);
CREATE INDEX pasu_attribute_lookup_idx ON pasu_attribute(pasu_id, attribute_type);

CREATE TABLE pasu_snapshot (
  id TEXT PRIMARY KEY,
  pasu_id TEXT NOT NULL REFERENCES pasu(id),
  snapshot TEXT NOT NULL CHECK(json_valid(snapshot)),
  disclosure TEXT NOT NULL DEFAULT 'private' CHECK(disclosure IN ('secret','private','shared','public')),
  source_attribute_ids TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(source_attribute_ids)),
  created_by TEXT REFERENCES actor(id),
  created_at TEXT NOT NULL
);

CREATE TABLE epi_session (
  id TEXT PRIMARY KEY,
  pasu_id TEXT REFERENCES pasu(id),
  parent_session_id TEXT REFERENCES epi_session(id),
  continuation_of_id TEXT REFERENCES epi_session(id),
  session_key_hash BLOB NOT NULL UNIQUE,
  harness TEXT,
  harness_session_ref TEXT,
  started_at TEXT NOT NULL,
  ended_at TEXT,
  timezone TEXT NOT NULL,
  locale TEXT,
  disclosure TEXT NOT NULL DEFAULT 'private' CHECK(disclosure IN ('secret','private','shared','public')),
  resumable_state TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(resumable_state)),
  last_event_sequence INTEGER NOT NULL DEFAULT 0,
  created_by TEXT REFERENCES actor(id),
  CHECK(ended_at IS NULL OR ended_at >= started_at)
);

CREATE TABLE temporal_snapshot (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL REFERENCES epi_session(id),
  event_time TEXT,
  observed_at TEXT NOT NULL,
  local_civil_time TEXT,
  timezone TEXT NOT NULL,
  location TEXT CHECK(location IS NULL OR json_valid(location)),
  location_precision TEXT,
  astronomy_provider TEXT,
  astronomy_version TEXT,
  astrology_profile_id TEXT,
  astrology_profile_version TEXT,
  astronomical_facts TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(astronomical_facts)),
  interpreted_contributions TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(interpreted_contributions)),
  disclosure TEXT NOT NULL DEFAULT 'private' CHECK(disclosure IN ('secret','private','shared','public')),
  created_at TEXT NOT NULL
);

CREATE TABLE configuration_profile (
  id TEXT NOT NULL,
  version TEXT NOT NULL,
  profile_type TEXT NOT NULL CHECK(profile_type IN ('ql_lens','ql_relation','mapping','disclosure','validation','duration','render','print','interaction','symbol_baseline','audio_tuning','audio_resonator','spatial','provider_policy','other')),
  status TEXT NOT NULL CHECK(status IN ('draft','active','deprecated','retired')),
  register TEXT NOT NULL DEFAULT 'ql_derived' CHECK(register IN ('exact_identity','ql_derived','canonical_symbolic','cross_register','archetypal_reception','open_extension')),
  content TEXT NOT NULL CHECK(json_valid(content)),
  content_hash TEXT NOT NULL CHECK(length(content_hash)=64),
  source_refs TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(source_refs)),
  change_log TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(change_log)),
  author_actor_id TEXT REFERENCES actor(id),
  reviewer_actor_ids TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(reviewer_actor_ids)),
  effective_from TEXT,
  effective_to TEXT,
  created_at TEXT NOT NULL,
  PRIMARY KEY(id,version),
  CHECK(effective_to IS NULL OR effective_from IS NULL OR effective_to > effective_from)
);

CREATE TABLE profile_set (
  id TEXT PRIMARY KEY,
  stable_key TEXT NOT NULL,
  version TEXT NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('draft','active','deprecated','retired')),
  set_hash TEXT NOT NULL UNIQUE CHECK(length(set_hash)=64),
  description TEXT,
  created_by TEXT REFERENCES actor(id),
  created_at TEXT NOT NULL,
  UNIQUE(stable_key,version)
);

CREATE TABLE profile_set_member (
  profile_set_id TEXT NOT NULL REFERENCES profile_set(id) ON DELETE CASCADE,
  registry TEXT NOT NULL CHECK(registry IN ('configuration','correspondence','projection','provider_capability')),
  profile_id TEXT NOT NULL,
  profile_version TEXT NOT NULL,
  precedence INTEGER NOT NULL DEFAULT 0,
  required INTEGER NOT NULL DEFAULT 1 CHECK(required IN (0,1)),
  PRIMARY KEY(profile_set_id,registry,profile_id,profile_version)
);

CREATE TABLE attractor (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL,
  stable_key TEXT UNIQUE,
  label TEXT NOT NULL,
  description TEXT,
  created_by TEXT REFERENCES actor(id),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE attractor_revision (
  id TEXT PRIMARY KEY,
  attractor_id TEXT NOT NULL REFERENCES attractor(id) ON DELETE CASCADE,
  revision_no INTEGER NOT NULL CHECK(revision_no > 0),
  label TEXT NOT NULL,
  description TEXT,
  metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata)),
  created_by TEXT REFERENCES actor(id),
  created_at TEXT NOT NULL,
  UNIQUE(attractor_id, revision_no)
);

CREATE TABLE basin_member (
  id TEXT PRIMARY KEY,
  attractor_revision_id TEXT NOT NULL REFERENCES attractor_revision(id) ON DELETE CASCADE,
  stable_local_key TEXT NOT NULL,
  label TEXT NOT NULL,
  description TEXT,
  relation TEXT NOT NULL CHECK(relation IN ('essential','constitutive','contextual','resonant','counterpole','boundary','excluded','unresolved')),
  weight REAL NOT NULL CHECK(weight >= 0 AND weight <= 1),
  register TEXT NOT NULL CHECK(register IN ('exact_identity','ql_derived','canonical_symbolic','cross_register','archetypal_reception','open_extension')),
  rationale TEXT NOT NULL,
  ql_candidate_addresses TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(ql_candidate_addresses)),
  valid_from TEXT,
  valid_to TEXT,
  disclosure TEXT NOT NULL DEFAULT 'private' CHECK(disclosure IN ('secret','private','shared','public')),
  created_by TEXT REFERENCES actor(id),
  created_at TEXT NOT NULL,
  UNIQUE(attractor_revision_id, stable_local_key, relation),
  CHECK(valid_to IS NULL OR valid_from IS NULL OR valid_to > valid_from)
);

CREATE TABLE engagement (
  id TEXT PRIMARY KEY,
  slug TEXT UNIQUE,
  pasu_snapshot_id TEXT REFERENCES pasu_snapshot(id),
  temporal_snapshot_id TEXT REFERENCES temporal_snapshot(id),
  attractor_revision_id TEXT NOT NULL REFERENCES attractor_revision(id),
  question TEXT,
  intention TEXT,
  active_lens_id TEXT NOT NULL,
  active_lens_version TEXT NOT NULL,
  profile_set TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(profile_set)),
  profile_set_id TEXT REFERENCES profile_set(id),
  disclosure TEXT NOT NULL DEFAULT 'private' CHECK(disclosure IN ('secret','private','shared','public')),
  status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','mapping','art_direction','production','review','approved','rendered','published','returned','archived')),
  current_revision INTEGER NOT NULL DEFAULT 1 CHECK(current_revision > 0),
  created_by TEXT REFERENCES actor(id),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE engagement_projection (
  id TEXT PRIMARY KEY,
  engagement_id TEXT NOT NULL REFERENCES engagement(id) ON DELETE CASCADE,
  projection_kind TEXT NOT NULL CHECK(projection_kind IN ('private','shared','public','provider')),
  revision_no INTEGER NOT NULL CHECK(revision_no > 0),
  disclosure TEXT NOT NULL CHECK(disclosure IN ('secret','private','shared','public')),
  provider TEXT,
  purpose TEXT,
  source_revision_manifest TEXT NOT NULL CHECK(json_valid(source_revision_manifest)),
  snapshot TEXT NOT NULL CHECK(json_valid(snapshot)),
  snapshot_hash TEXT NOT NULL UNIQUE CHECK(length(snapshot_hash)=64),
  status TEXT NOT NULL CHECK(status IN ('draft','approved','superseded','expired')),
  expires_at TEXT,
  created_by TEXT REFERENCES actor(id),
  approved_by TEXT REFERENCES actor(id),
  created_at TEXT NOT NULL,
  approved_at TEXT,
  UNIQUE(engagement_id,projection_kind,provider,purpose,revision_no),
  CHECK((projection_kind='provider' AND provider IS NOT NULL AND purpose IS NOT NULL) OR projection_kind<>'provider')
);
CREATE INDEX engagement_projection_lookup_idx ON engagement_projection(engagement_id,projection_kind,status,revision_no DESC);

CREATE TABLE resource_lock (
  id TEXT PRIMARY KEY,
  engagement_id TEXT NOT NULL REFERENCES engagement(id) ON DELETE CASCADE,
  target_kind TEXT NOT NULL,
  target_id TEXT NOT NULL,
  field_path TEXT NOT NULL DEFAULT '',
  lock_type TEXT NOT NULL CHECK(lock_type IN ('semantic','symbol_geometry','palette_token','typography','scene_intent','plate','audio_tuning','render','publication')),
  reason TEXT NOT NULL,
  locked_by TEXT NOT NULL REFERENCES actor(id),
  locked_at TEXT NOT NULL,
  expires_at TEXT,
  released_by TEXT REFERENCES actor(id),
  released_at TEXT,
  release_reason TEXT,
  CHECK(released_at IS NULL OR released_at >= locked_at),
  CHECK(expires_at IS NULL OR expires_at > locked_at)
);
CREATE UNIQUE INDEX resource_lock_active_unique_idx ON resource_lock(engagement_id,target_kind,target_id,field_path) WHERE released_at IS NULL;

CREATE TABLE engagement_session (
  engagement_id TEXT NOT NULL REFERENCES engagement(id) ON DELETE CASCADE,
  session_id TEXT NOT NULL REFERENCES epi_session(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK(role IN ('originating','continuing','reviewing','publishing')),
  joined_at TEXT NOT NULL,
  PRIMARY KEY(engagement_id, session_id, role)
);

CREATE TABLE talismanic_activation (
  id TEXT PRIMARY KEY,
  engagement_id TEXT NOT NULL UNIQUE REFERENCES engagement(id) ON DELETE CASCADE,
  intent_statement TEXT NOT NULL,
  recipient_pasu_id TEXT REFERENCES pasu(id),
  activation_scope TEXT,
  activation_at TEXT,
  activation_event TEXT,
  review_at TEXT,
  expiry_condition TEXT,
  return_condition TEXT,
  handling_notes TEXT,
  private_phrase_ref TEXT,
  cadence_or_repetition TEXT CHECK(cadence_or_repetition IS NULL OR json_valid(cadence_or_repetition)),
  disclosure TEXT NOT NULL DEFAULT 'private' CHECK(disclosure IN ('secret','private','shared','public')),
  created_by TEXT REFERENCES actor(id),
  created_at TEXT NOT NULL
);

CREATE TABLE activation_witness (
  activation_id TEXT NOT NULL REFERENCES talismanic_activation(id) ON DELETE CASCADE,
  actor_id TEXT NOT NULL REFERENCES actor(id),
  role TEXT NOT NULL DEFAULT 'witness',
  PRIMARY KEY(activation_id, actor_id, role)
);

CREATE TABLE source_form (
  id TEXT PRIMARY KEY,
  engagement_id TEXT NOT NULL REFERENCES engagement(id) ON DELETE CASCADE,
  source_kind TEXT NOT NULL,
  declared_arity INTEGER CHECK(declared_arity >= 0),
  native_relations TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(native_relations)),
  source_ref TEXT,
  notes TEXT,
  disclosure TEXT NOT NULL DEFAULT 'private' CHECK(disclosure IN ('secret','private','shared','public')),
  created_by TEXT REFERENCES actor(id),
  created_at TEXT NOT NULL
);

CREATE TABLE source_member (
  id TEXT PRIMARY KEY,
  source_form_id TEXT NOT NULL REFERENCES source_form(id) ON DELETE CASCADE,
  ordinal INTEGER,
  member_key TEXT,
  content TEXT NOT NULL CHECK(json_valid(content)),
  disclosure TEXT NOT NULL DEFAULT 'private' CHECK(disclosure IN ('secret','private','shared','public')),
  created_at TEXT NOT NULL,
  UNIQUE(source_form_id, ordinal),
  UNIQUE(source_form_id, member_key)
);

CREATE TABLE asset (
  id TEXT PRIMARY KEY,
  sha256 TEXT NOT NULL UNIQUE CHECK(length(sha256)=64 AND sha256 NOT GLOB '*[^0-9a-f]*'),
  uri TEXT NOT NULL,
  media_type TEXT NOT NULL,
  role TEXT NOT NULL CHECK(role IN ('source','reference','candidate','canonical','intermediate','rendition','poster','mask','symbol','font_outline','audio_layer','transcript','storyboard','print','knowledge_export','validation_report')),
  byte_length INTEGER CHECK(byte_length IS NULL OR byte_length >= 0),
  width INTEGER CHECK(width IS NULL OR width > 0),
  height INTEGER CHECK(height IS NULL OR height > 0),
  duration_ms INTEGER CHECK(duration_ms IS NULL OR duration_ms >= 0),
  alpha_mode TEXT NOT NULL DEFAULT 'none' CHECK(alpha_mode IN ('none','straight','premultiplied')),
  colour_profile TEXT,
  sample_rate INTEGER CHECK(sample_rate IS NULL OR sample_rate > 0),
  bit_depth INTEGER CHECK(bit_depth IS NULL OR bit_depth > 0),
  rights_status TEXT NOT NULL DEFAULT 'unknown',
  licence TEXT,
  creator_actor_id TEXT REFERENCES actor(id),
  provider TEXT,
  model_id TEXT,
  model_version TEXT,
  disclosure TEXT NOT NULL DEFAULT 'private' CHECK(disclosure IN ('secret','private','shared','public')),
  metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata)),
  created_at TEXT NOT NULL
);

CREATE TABLE asset_derivation (
  output_asset_id TEXT NOT NULL REFERENCES asset(id) ON DELETE CASCADE,
  input_asset_id TEXT NOT NULL REFERENCES asset(id),
  relation TEXT NOT NULL CHECK(relation IN ('derived_from','references','contains','mask_of','mixes','continues')),
  operation_name TEXT,
  operation_version TEXT,
  parameters TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(parameters)),
  sequence_no INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY(output_asset_id, input_asset_id, relation, sequence_no),
  CHECK(output_asset_id <> input_asset_id)
);

CREATE TABLE recording (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL REFERENCES epi_session(id),
  engagement_id TEXT REFERENCES engagement(id),
  asset_id TEXT NOT NULL REFERENCES asset(id),
  recorded_at TEXT,
  speaker_map TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(speaker_map)),
  consent_state TEXT NOT NULL,
  language_hints TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(language_hints)),
  capture_metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(capture_metadata)),
  disclosure TEXT NOT NULL DEFAULT 'private' CHECK(disclosure IN ('secret','private','shared','public')),
  created_at TEXT NOT NULL
);

CREATE TABLE transcript (
  id TEXT PRIMARY KEY,
  recording_id TEXT NOT NULL REFERENCES recording(id) ON DELETE CASCADE,
  provider TEXT NOT NULL,
  model_id TEXT NOT NULL,
  model_version TEXT,
  language TEXT,
  diarisation_map TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(diarisation_map)),
  transcript_asset_id TEXT REFERENCES asset(id),
  digest TEXT CHECK(digest IS NULL OR length(digest)=64),
  created_at TEXT NOT NULL
);

CREATE TABLE transcript_segment (
  id TEXT PRIMARY KEY,
  transcript_id TEXT NOT NULL REFERENCES transcript(id) ON DELETE CASCADE,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  speaker_ref TEXT,
  start_ms INTEGER NOT NULL CHECK(start_ms >= 0),
  end_ms INTEGER NOT NULL CHECK(end_ms > start_ms),
  text TEXT NOT NULL,
  confidence REAL CHECK(confidence IS NULL OR (confidence >= 0 AND confidence <= 1)),
  redacted INTEGER NOT NULL DEFAULT 0 CHECK(redacted IN (0,1)),
  disclosure TEXT NOT NULL DEFAULT 'private' CHECK(disclosure IN ('secret','private','shared','public')),
  UNIQUE(transcript_id, ordinal)
);

CREATE TABLE ql_canonical_position (
  phase TEXT NOT NULL CHECK(phase IN ('bimba','pratibimba')),
  position_index INTEGER NOT NULL CHECK(position_index BETWEEN 0 AND 5),
  address TEXT NOT NULL,
  canonical_unit TEXT NOT NULL,
  canonical_question TEXT NOT NULL,
  structural_role TEXT NOT NULL,
  PRIMARY KEY(phase, position_index),
  UNIQUE(address)
);

